    return {
        requestDuration: metrics.histogram("pi.ai.request.duration"),
        firstChunkDuration: metrics.histogram("pi.ai.first_chunk.duration"),
        tokens: metrics.counter("pi.ai.tokens"),
        cost: metrics.counter("pi.ai.cost"),
